.ta-vie-product-stories {
  background: var(--COLOR-BG);
  color: var(--COLOR-TEXT);
}

.ta-vie-product-stories > .wrapper--full-padded {
  max-width: 1600px;
  margin-inline: auto;
}

.ta-vie-product-stories__intro {
  max-width: 760px;
  margin: 0 0 clamp(40px, 6vw, 88px);
}

.ta-vie-product-stories__eyebrow,
.ta-vie-product-story__eyebrow {
  margin: 0 0 16px;
  font-size: 12px;
  line-height: 1.6;
  letter-spacing: 0.08em;
}

.ta-vie-product-stories__heading,
.ta-vie-product-story__title,
.ta-vie-product-story__detail-heading {
  margin: 0;
  font-family: var(--FONT-STACK-HEADING);
  font-weight: var(--FONT-WEIGHT-HEADING);
  line-break: strict;
  overflow-wrap: anywhere;
  word-break: normal;
  text-wrap: balance;
}

.ta-vie-product-stories__heading {
  font-size: clamp(32px, 3.4vw, 54px);
  line-height: 1.4;
}

.ta-vie-product-stories__intro-copy {
  max-width: 36em;
  margin-top: 20px;
}

.ta-vie-product-story + .ta-vie-product-story {
  margin-top: clamp(88px, 12vw, 176px);
}

.ta-vie-product-story__stage,
.ta-vie-product-story__detail {
  display: grid;
  grid-template-columns: minmax(0, 1.75fr) minmax(0, 1fr);
  gap: clamp(36px, 6vw, 88px);
  align-items: center;
}

.ta-vie-product-story__media,
.ta-vie-product-story__scene-image,
.ta-vie-product-story__detail-media {
  position: relative;
  min-width: 0;
  overflow: hidden;
  background: var(--COLOR-BG-ACCENT);
}

.ta-vie-product-story__media {
  width: 100%;
  aspect-ratio: 4 / 5;
  max-height: 980px;
}

.ta-vie-product-story__image {
  height: 100%;
  margin: 0;
  padding-top: 0;
}

.ta-vie-product-story__media > .desktop,
.ta-vie-product-story__media > .mobile {
  height: 100%;
}

.ta-vie-product-story__media--contain img {
  object-fit: contain;
}

.ta-vie-product-story__media--cover img,
.ta-vie-product-story__scene-image img,
.ta-vie-product-story__detail-media img {
  object-fit: cover;
}

.ta-vie-product-story__copy {
  min-width: 0;
  max-width: 420px;
  padding-block: 24px;
}

.ta-vie-product-story__title {
  font-size: clamp(28px, 3vw, 44px);
  line-height: 1.45;
}

.ta-vie-product-stories__intro-copy,
.ta-vie-product-story__intro,
.ta-vie-product-story__detail-text,
.ta-vie-product-story__caption {
  font-size: 16px;
  line-height: 1.85;
  overflow-wrap: anywhere;
}

.ta-vie-product-story__intro {
  margin-top: 24px;
}

.ta-vie-product-story__intro > :first-child,
.ta-vie-product-story__detail-text > :first-child,
.ta-vie-product-story__caption > :first-child,
.ta-vie-product-stories__intro-copy > :first-child {
  margin-top: 0;
}

.ta-vie-product-story__intro > :last-child,
.ta-vie-product-story__detail-text > :last-child,
.ta-vie-product-story__caption > :last-child,
.ta-vie-product-stories__intro-copy > :last-child {
  margin-bottom: 0;
}

.ta-vie-product-story__intro img,
.ta-vie-product-story__detail-text img {
  max-width: 100%;
  height: auto;
}

.ta-vie-product-story__price {
  margin-top: 28px;
  font-size: 16px;
}

.ta-vie-product-story__button {
  margin-top: 24px;
}

.ta-vie-product-story__scene {
  margin: clamp(40px, 7vw, 104px) 0 0;
}

.ta-vie-product-story__scene-image {
  aspect-ratio: 16 / 10;
  height: auto;
  margin: 0;
  padding-top: 0;
}

.ta-vie-product-story__caption {
  max-width: 40em;
  margin: 16px 0 0;
}

.ta-vie-product-story__detail {
  max-width: 1240px;
  margin: clamp(40px, 7vw, 104px) auto 0;
  grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr);
}

.ta-vie-product-story__detail-media {
  aspect-ratio: 1;
}

.ta-vie-product-story__detail--image-only {
  display: block;
  max-width: 720px;
}

.ta-vie-product-story__detail-copy {
  min-width: 0;
  max-width: 400px;
}

.ta-vie-product-story__detail-heading {
  font-size: clamp(24px, 2vw, 32px);
  line-height: 1.5;
}

.ta-vie-product-story__detail-text {
  margin-top: 20px;
}

.ta-vie-product-story--text-only .ta-vie-product-story__stage {
  grid-template-columns: minmax(0, 1fr);
}

.ta-vie-product-stories__editor-note {
  margin-block: 32px;
  padding: 24px;
  border: 1px solid var(--COLOR-BORDER);
  background: var(--COLOR-BG-ACCENT);
  font-size: 16px;
  line-height: 1.8;
}

.ta-vie-product-stories__all-link {
  margin-top: clamp(56px, 8vw, 112px);
  text-align: center;
}

@media only screen and (min-width: 990px) {
  .ta-vie-product-story--image-right .ta-vie-product-story__stage {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1.75fr);
  }

  .ta-vie-product-story--image-right .ta-vie-product-story__media {
    grid-column: 2;
    grid-row: 1;
  }

  .ta-vie-product-story--image-right .ta-vie-product-story__copy {
    grid-column: 1;
    grid-row: 1;
  }

  .ta-vie-product-story--text-only .ta-vie-product-story__stage {
    grid-template-columns: minmax(0, 1fr);
  }

  .ta-vie-product-story--text-only .ta-vie-product-story__copy {
    grid-column: 1;
  }

  .ta-vie-product-story__detail--image-right {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1.2fr);
  }

  .ta-vie-product-story__detail--image-right .ta-vie-product-story__detail-media {
    grid-column: 2;
    grid-row: 1;
  }

  .ta-vie-product-story__detail--image-right .ta-vie-product-story__detail-copy {
    grid-column: 1;
    grid-row: 1;
  }
}

@media only screen and (max-width: 989px) {
  .ta-vie-product-story__stage,
  .ta-vie-product-story__detail {
    grid-template-columns: minmax(0, 1fr);
    gap: 24px;
  }

  .ta-vie-product-story__copy {
    padding-block: 8px;
  }

  .ta-vie-product-story__scene-image {
    aspect-ratio: 4 / 5;
  }
}

